sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float blurLength;
uniform float angle;
uniform float spread;

half4 main(float2 coord) {
    float rad = radians(angle);
    float2 dir = float2(cos(rad), sin(rad));
    bool both = spread > 0.5;
    float n = both ? 128.0 : 32.0;
    float4 accum = float4(0.0);
    for (int i = 0; i < 128; ++i) {
        if (float(i) >= n) break;
        float t = float(i) / (n - 1.0);
        float2 offset = dir * (t - (both ? 0.5 : 0.0)) * blurLength;
        float2 sampleCoord = coord - offset;
        accum += float4(image.eval(sampleCoord));
    }
    return half4(accum / n);
}
